var typographicApostrophes = strings.NewReplacer("’", "'", "‘", "'", "ʼ", "'")

var scriptLanguages = []struct {
	lang string
	test func(rune) bool
}{
	{"ja", func(r rune) bool { return unicode.Is(unicode.Hiragana, r) || unicode.Is(unicode.Katakana, r) }},
	{"ko", func(r rune) bool { return unicode.Is(unicode.Hangul, r) }},
	{"zh", func(r rune) bool { return unicode.Is(unicode.Han, r) }},
	{"ru", func(r rune) bool { return unicode.Is(unicode.Cyrillic, r) }},
	{"ar", func(r rune) bool { return unicode.Is(unicode.Arabic, r) }},
}

func detectLanguage(text string) string {
	sample := text
	if len(sample) > 1200 {
		sample = sample[:1200]
	}
	counts := map[string]int{}
	letters := 0
	for _, r := range sample {
		if !unicode.IsLetter(r) {
			continue
		}
		letters++
		for _, script := range scriptLanguages {
			if script.test(r) {
				counts[script.lang]++
				break
			}
		}
	}
	if letters == 0 {
		return ""
	}

	if counts["ja"] >= 2 {
		return "ja"
	}
	for _, script := range scriptLanguages {
		if script.lang != "ja" && counts[script.lang]*4 >= letters && counts[script.lang] >= 3 {
			return script.lang
		}
	}
	var words []string
	for _, token := range strings.FieldsFunc(typographicApostrophes.Replace(strings.ToLower(sample)), func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsDigit(r) && !strings.ContainsRune("'.-/", r)
	}) {
		words = appendTokenWords(words, token)
	}
	if len(words) < 2 {
		return ""
	}
	scores := map[string]int{}
	exclusive := map[string]int{}
	turkishLetters := 0
	polishLetters := 0
	for _, word := range words {
		owners, owner := 0, ""
		for lang, list := range stopWords {
			if slices.Contains(list, word) {
				scores[lang]++
				owners++
				owner = lang
			}
		}
		if owners == 1 {
			exclusive[owner]++
		}
		if strings.ContainsAny(word, "şğıİ") {
			turkishLetters++
		}
		if strings.ContainsAny(word, "łąężźśćń") {
			polishLetters++
		}
	}
	scores["tr"] += turkishLetters * 2
	scores["pl"] += polishLetters * 2
	exclusive["tr"] += turkishLetters * 2
	exclusive["pl"] += polishLetters * 2
	best, second, bestLang := 0, 0, ""
	for lang, score := range scores {
		switch {
		case score > best:
			second, best, bestLang = best, score, lang
		case score > second:
			second = score
		}
	}
	if best-second < 1 || (best < 3 && exclusive[bestLang] < 2) {
		return ""
	}
	return bestLang
}

func appendTokenWords(words []string, token string) []string {
	token = strings.TrimLeft(strings.TrimRight(token, "'."), "'")
	if strings.Contains(token, "/") {
		for _, part := range strings.Split(token, "/") {
			if part = strings.TrimLeft(strings.TrimRight(part, "'."), "'"); utf8.RuneCountInString(part) > 1 {
				words = appendTokenWords(words, part)
			}
		}
		return words
	}
	if !strings.ContainsFunc(token, unicode.IsLetter) {
		return words
	}
	if !strings.Contains(token, "-") || strings.HasPrefix(token, "-") || strings.ContainsFunc(token, func(r rune) bool { return r == '.' || unicode.IsDigit(r) }) {
		return append(words, token)
	}
	parts := strings.FieldsFunc(token, func(r rune) bool { return r == '-' })
	for i, part := range parts {
		parts[i] = strings.Trim(part, "'")
		if !listedWord(parts[i]) {
			return append(words, token)
		}
	}
	return append(words, parts...)
}

func listedWord(word string) bool {
	for _, list := range stopWords {
		if slices.Contains(list, word) {
			return true
		}
	}
	return false
}

func rememberSessionLanguage(sid, text string) string {
	lang := detectLanguage(text)
	if lang == "" || sid == "" {
		return ""
	}
	state := readState()
	if getString(getMap(getMap(state, "sessionLocale"), sid), "lang") != lang {
		updateState(func(next object) {
			stateMap(next, "sessionLocale")[sid] = object{"lang": lang, "at": float64(nowSec())}
		})
	}
	return lang
}

func sessionLanguage(state object, sid string) string {
	return getString(getMap(getMap(state, "sessionLocale"), sid), "lang")
}

func applySessionLocale(cfg object, state object, sid string) {
	if strings.ToLower(strings.TrimSpace(getString(cfg, "locale"))) != "auto" && getString(cfg, "locale") != "" {
		return
	}
	if os.Getenv("NOCTIS_LANG") != "" {
		return
	}
	if lang := sessionLanguage(state, sid); lang != "" && knownLocale(lang) {
		locale = lang
	}
}

